1	// Data contract between the Python agent (agent/export.py) and the web viewer.
2	// The Python side writes these files into web/public/data/. Keep both sides in sync.
3	
4	/** web/public/data/manifest.json */
5	export interface Manifest {
6	  generated_at: string;
7	  default_run: string;
8	  runs: { id: string; label: string; file: string }[];
9	}
10	
11	/** Signals. Inputs come from the operator panel and the plant; outputs and coils from the PLC program. */
12	export const INPUTS = ['START', 'STOP', 'ESTOP', 'RESET', 'GUARD_CLOSED', 'PE_IN', 'PE_END'] as const;
13	export const OUTPUTS = ['MOTOR', 'LAMP_GREEN', 'LAMP_AMBER', 'LAMP_RED'] as const;
14	export type InputName = (typeof INPUTS)[number];
15	export type OutputName = (typeof OUTPUTS)[number];
16	
17	/** Plant geometry, in metres and seconds. Mirrors agent/plc/plant.py. */
18	export const PLANT = {
19	  dt: 0.1, // scan time
20	  beltLength: 4.0, // belt runs from x=0 (infeed) to x=4.0 (discharge end)
21	  beltSpeed: 0.5, // m/s while MOTOR=1
22	  boxLength: 0.4,
23	  peIn: 0.3, // photo-eye at the infeed
24	  peEnd: 3.7, // photo-eye at the pick position
25	  dropX: 3.9, // a box whose centre passes this falls off the end
26	} as const;
27	
28	/** One rung of the restricted control language ("ladder-lite"). */
29	export type Expr =
30	  | { op: 'var'; name: string }
31	  | { op: 'timer'; name: string } // T_NAME.Q
32	  | { op: 'rise'; name: string } // RISE(X): rising edge since the previous scan
33	  | { op: 'const'; value: boolean }
34	  | { op: 'not'; arg: Expr }
35	  | { op: 'and'; args: Expr[] }
36	  | { op: 'or'; args: Expr[] };
37	
38	export interface Rung {
39	  id: string; // stable id, e.g. "R06"
40	  text: string; // source text, e.g. "RUN = (RISE(START) OR RUN) AND NOT STOP"
41	  kind: 'assign' | 'set' | 'reset' | 'ton';
42	  target: string; // coil or timer name
43	  expr: Expr; // for 'ton' this is the timer's IN condition
44	  pt?: number; // timer preset in seconds ('ton' only)
45	  comment?: string;
46	}
47	
48	export interface SpecRule {
49	  id: string; // "S1".."S7", "F1".."F6"
50	  title: string;
51	  text: string;
52	  kind: 'safety' | 'functional';
53	  method: 'proof' | 'simulation';
54	}
55	
56	/** One scan of a simulated scenario. Values are 0/1 so the JSON stays small. */
57	export interface Frame {
58	  t: number;
59	  in: Record<string, 0 | 1>;
60	  out: Record<string, 0 | 1>;
61	  coil: Record<string, 0 | 1>;
62	  timer: Record<string, number>; // elapsed seconds
63	  boxes: { id: number; x: number; state: 'belt' | 'picked' | 'dropped' }[];
64	  stuck?: { PE_IN?: 0 | 1; PE_END?: 0 | 1 }; // present while a sensor is forced
65	}
66	
67	export interface Violation {
68	  rule: string; // spec rule id, or "DROP" when a box falls off the end
69	  t: number;
70	  message: string;
71	}
72	
73	export interface TraceEvent {
74	  t: number;
75	  kind: 'press' | 'release' | 'set' | 'spawn' | 'pick' | 'stick' | 'unstick' | 'drop';
76	  label: string; // human text, e.g. "Operator presses START"
77	}
78	
79	export interface Trace {
80	  dt: number;
81	  frames: Frame[];
82	  violations: Violation[];
83	  events: TraceEvent[];
84	}
85	
86	export interface ScenarioPair {
87	  id: string;
88	  title: string;
89	  description: string;
90	  baseline: Trace; // the program the agent was given
91	  repaired: Trace; // the program the agent submitted
92	}
93	
94	export interface ProofResult {
95	  rule: string;
96	  status: 'proven' | 'violated';
97	  states_explored: number;
98	  counterexample?: { t: number; in: Record<string, 0 | 1>; out: Record<string, 0 | 1> }[];
99	}
100	
101	export interface EvalSummary {
102	  visible: { pass: number; total: number };
103	  heldout: { pass: number; total: number };
104	  proofs: ProofResult[];
105	  fuzz: { episodes: number; violations: number; by_rule: Record<string, number> };
106	  faults_fixed: { fixed: number; total: number };
107	}
108	
109	export interface StepMetrics {
110	  visible_pass: number;
111	  visible_total: number;
112	  proven: number;
113	  proof_total: number;
114	}
115	
116	export interface Step {
117	  i: number;
118	  t: number; // seconds since the run started
119	  kind: 'think' | 'tool' | 'patch' | 'rollback' | 'submit' | 'error' | 'recover';
120	  tool?: string;
121	  title: string; // one line, shown in the timeline
122	  detail?: string; // longer text: the agent's reasoning or the tool result
123	  args?: unknown;
124	  ok?: boolean;
125	  program_version?: string; // program version in force after this step
126	  tokens?: number;
127	  cost_usd?: number;
128	  metrics?: StepMetrics;
129	}
130	
131	/** web/public/data/runs/<id>.json */
132	export interface RunFile {
133	  id: string;
134	  label: string;
135	  agent: 'v1' | 'v2';
136	  model: string;
137	  provider: string;
138	  started_at: string;
139	  duration_s: number;
140	  tokens: { input: number; output: number };
141	  cost_usd: number;
142	  neatlogs_url?: string;
143	  spec: SpecRule[];
144	  programs: Record<string, Rung[]>; // "v0" is the baseline, then one version per accepted patch
145	  final_version: string;
146	  steps: Step[];
147	  eval: { baseline: EvalSummary; repaired: EvalSummary };
148	  scenarios: ScenarioPair[];
149	}
150

