    this.alu = this.m(
      new THREE.MeshStandardMaterial({
        color: 0xc9cdd3,
        metalness: 1,
        roughness: 0.42,
        roughnessMap: this.brushed,
        envMapIntensity: 1.15,
      }),
    );
    this.aluDark = this.m(new THREE.MeshStandardMaterial({ color: 0x2c2f34, metalness: 0.75, roughness: 0.38 }));
    this.steel = this.m(
      new THREE.MeshStandardMaterial({ color: 0xdfe2e6, metalness: 1, roughness: 0.22, roughnessMap: this.brushed }),
    );
    this.steelDark = this.m(new THREE.MeshStandardMaterial({ color: 0x5d6168, metalness: 1, roughness: 0.42 }));
    this.chrome = this.m(new THREE.MeshStandardMaterial({ color: 0xf2f4f7, metalness: 1, roughness: 0.08 }));
    this.zinc = this.m(new THREE.MeshStandardMaterial({ color: 0xb8bcc2, metalness: 1, roughness: 0.35 }));

    this.belt = this.m(
      new THREE.MeshStandardMaterial({
